// Cloudflare Email configuration from environment (uses send_email binding — zero API keys)
function getEmail(
  env: CloudflareBindings,
  schedule: (delivery: Promise<unknown>) => Promise<void>,
) {
  if (!env.EMAIL) {
    throw new Error('Cloudflare Email binding is not configured');
  }
  const from = env.EMAIL_FROM_NAME
    ? { email: env.EMAIL_FROM || 'noreply@example.com', name: env.EMAIL_FROM_NAME }
    : env.EMAIL_FROM || 'noreply@example.com';
  return cloudflareEmail.workers({
    binding: env.EMAIL,
    from,
    appName: env.APP_NAME || 'App',
    schedule,
  });
}

// Deep-merge so cloudflareEmail.config (sendResetPassword, sendVerificationEmail, …)
// composes with the user's per-block options instead of getting clobbered by them.
// JS object spread is shallow, so { ...{ emailAndPassword: { sendResetPassword } },
// emailAndPassword: { enabled: true } } loses sendResetPassword — this avoids that.
function mergeAuthOptions<T extends Record<string, any>>(base: any, over: any): T {
  if (!base) return over as T;
  if (!over) return base as T;
  const out: any = { ...base };
  for (const k of Object.keys(over)) {
    const a = base[k];
    const b = over[k];
    if (
      a && typeof a === 'object' && !Array.isArray(a) && typeof a !== 'function' &&
      b && typeof b === 'object' && !Array.isArray(b) && typeof b !== 'function'
    ) {
      out[k] = mergeAuthOptions(a, b);
    } else {
      out[k] = b;
    }
  }
  return out as T;
}

export const TRUSTED_ORIGINS = ["http://localhost:8787","http://localhost:3000","http://localhost:5173","http://127.0.0.1:8765","http://localhost:8765","http://127.0.0.1:4173","http://localhost:4173"] as const;

// EXTRA_APP_HOSTS (comma-separated hostnames) extends Better Auth's own
// origin check the same way it extends the CORS + apps allowlists — Better
// Auth validates Origin against trustedOrigins independently of cors(), so
// stopping at the CORS layer left preview/dev deploys passing preflight and
// then failing auth. Entries are hostnames (scheme added as https://); a
// full origin with scheme is passed through verbatim.
function extraTrustedOrigins(env: any): string[] {
  const raw: string | undefined = env?.EXTRA_APP_HOSTS;
  if (!raw) return [];
  return raw
    .split(',')
    .map((s: string) => s.trim())
    .filter(Boolean)
    .map((h: string) => (h.includes('://') ? h : 'https://' + h));
}

// ── Admin role ceiling ─────────────────────────────────────────────────────
// Better Auth's admin plugin lets any role holding user:set-role grant ANY
// role that exists — including one above its own — and lets adminAc ban,
// delete or reset the password of a higher-ranked user. Tiers ascend with the
// admin plugin's adminRoles order (every other role is tier 0): a caller may
// assign roles up to its own tier and act only on users at or below it.
const ADMIN_ROLE_TIERS: Readonly<Record<string, number>> = {"appmanager":1,"sysadmin":2};
// Better Auth treats an empty user.role as the admin plugin's defaultRole.
const ADMIN_ROLE_FALLBACK = "user";
const ROLE_CEILING_ASSIGN_PATHS: ReadonlySet<string> = new Set(["/admin/set-role","/admin/create-user","/admin/update-user"]);
const ROLE_CEILING_TARGET_PATHS: ReadonlySet<string> = new Set(["/admin/set-role","/admin/update-user","/admin/ban-user","/admin/remove-user","/admin/set-user-password","/admin/revoke-user-sessions","/admin/revoke-user-session","/admin/impersonate-user"]);

/** Highest admin tier held by a role value: a role name, a comma-separated list, or an array. Roles outside the tier table are tier 0. */
function roleCeilingTier(role: unknown, tiers: Readonly<Record<string, number>>): number {
  const names: unknown[] = Array.isArray(role) ? role : typeof role === 'string' ? role.split(',') : [];
  let tier = 0;
  for (const name of names) {
    if (typeof name !== 'string') continue;
    const key = name.trim();
    const value = Object.prototype.hasOwnProperty.call(tiers, key) ? tiers[key] : undefined;
    if (typeof value === 'number' && value > tier) tier = value;
  }
  return tier;
}

/** A caller may assign roles up to, and including, its own tier. */
function roleCeilingMayAssign(callerRole: unknown, requestedRole: unknown, tiers: Readonly<Record<string, number>>): boolean {
  return roleCeilingTier(requestedRole, tiers) <= roleCeilingTier(callerRole, tiers);
}

/** A caller may act on users whose current tier is at or below its own. */
function roleCeilingMayTarget(callerRole: unknown, targetRole: unknown, tiers: Readonly<Record<string, number>>): boolean {
  return roleCeilingTier(targetRole, tiers) <= roleCeilingTier(callerRole, tiers);
}

type AdminRoleCeilingContext = Parameters<typeof getAuthoritativeSessionFromCtx>[0];

async function enforceAdminRoleCeiling(ctx: AdminRoleCeilingContext): Promise<void> {
  const path: string = ctx.path;
  const assigns = ROLE_CEILING_ASSIGN_PATHS.has(path);
  const targets = ROLE_CEILING_TARGET_PATHS.has(path);
  if (!assigns && !targets) return;
  const body: any = ctx.body ?? {};
  const requested: unknown[] = [];
  if (assigns) {
    const data: any = body.data !== null && typeof body.data === 'object' ? body.data : undefined;
    if (path !== '/admin/update-user' && body.role !== undefined) requested.push(body.role);
    if (path !== '/admin/set-role' && data && Object.prototype.hasOwnProperty.call(data, 'role')) requested.push(data.role);
    // create-user with no role lands on defaultRole — that is an assignment too.
    if (path === '/admin/create-user' && requested.length === 0) requested.push(ADMIN_ROLE_FALLBACK);
  }
  if (requested.length === 0 && !targets) return;

  // No session: do nothing — Better Auth's own admin middleware answers 401
  // (and create-user stays callable server-side, as Better Auth intends).
  const session = await getAuthoritativeSessionFromCtx(ctx);
  if (!session) return;
  const callerRole: unknown = (session.user as any)?.role || ADMIN_ROLE_FALLBACK;

  for (const role of requested) {
    if (!roleCeilingMayAssign(callerRole, role, ADMIN_ROLE_TIERS)) {
      throw new APIError('FORBIDDEN', { code: "ROLE_CEILING", message: "Role ceiling: you cannot assign a role ranked above your own. Admin roles rank appmanager < sysadmin." });
    }
  }
  if (!targets) return;

  let target: any = null;
  if (path === '/admin/revoke-user-session') {
    const token = body.sessionToken;
    const found = typeof token === 'string' && token ? await ctx.context.internalAdapter.findSession(token) : null;
    target = found?.user ?? null;
  } else if (body.userId !== undefined && body.userId !== null && body.userId !== '') {
    target = await ctx.context.internalAdapter.findUserById(String(body.userId));
  }
  // Unknown user or session: do nothing — Better Auth answers 404 (or no-ops).
  if (!target) return;
  if (!roleCeilingMayTarget(callerRole, target.role || ADMIN_ROLE_FALLBACK, ADMIN_ROLE_TIERS)) {
    throw new APIError('FORBIDDEN', { code: "ROLE_CEILING", message: "Role ceiling: you cannot act on a user whose role ranks above your own. Admin roles rank appmanager < sysadmin." });
  }
}



